arguments.file_text:
@page "/"
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1>Welcome to the University Course Catalog</h1>
    <p class="lead">Explore our departments and find the courses that shape your future.</p>
</div>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text">@course.Credits credits · @course.DepartmentName</p>
                        <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="row">
        @foreach (var dept in departments)
        {
            <div class="col-md-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text"><strong>@dept.Abbreviation</strong></p>
                        <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">Browse Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<UniversityCourseCatalog.Models.Course> featuredCourses = [];
    private List<UniversityCourseCatalog.Models.Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = [];
    private List<UniversityCourseCatalog.Models.Department> departments = [];

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    <PageTitle>@course.CourseCode – @course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.CourseCode – @course.Title</h1>
    <span class="badge bg-secondary mb-3">@course.DepartmentName</span>

    <div class="row mt-3">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4>Schedule</h4>
            <p>@course.Schedule</p>

            <h4>Credits</h4>
            <p>@course.Credits</p>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.InstructorName</h6>
                    <p class="card-text">@course.InstructorBio</p>
                </div>
            </div>

            <div class="mt-3">
                <a href="/enroll?courseId=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Request Enrollment</h1>
<p>Fill out the form below to submit an enrollment request. You will be notified once your request is processed.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Enrollment request submitted!</strong> Your request for <em>@selectedCourseTitle</em> has been received.
    </div>
    <a href="/courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <form method="post" class="col-md-6">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control"
                   pattern="[A-Z0-9]{6,10}" title="6-10 uppercase alphanumeric characters" required />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode – @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = [];
    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;

        if (HttpMethods.IsPost(HttpContext.Request.Method))
        {
            if (CatalogService.SubmitEnrollmentRequest(Model))
            {
                var selectedCourse = CatalogService.GetCourse(Model.CourseId);
                selectedCourseTitle = selectedCourse is not null
                    ? $"{selectedCourse.CourseCode} – {selectedCourse.Title}"
                    : "Unknown";
                submitted = true;
            }
        }
    }

    [CascadingParameter] public HttpContext HttpContext { get; set; } = default!;
}

